// Inline page sources into TS string modules so the Worker serves them with
// zero build tooling. Generated files are committed; never edit them by hand.
const PAGES: { src: string; out: string; inject: Record<string, string> }[] = [
  { src: "server/viewer.html", out: "server/viewer-html.ts", inject: { "<!-- inject:viewer-md.js -->": "server/viewer-md.js" } },
  { src: "server/delete.html", out: "server/delete-html.ts", inject: {} },
  { src: "server/landing.html", out: "server/landing-html.ts", inject: {} },
];

for (const p of PAGES) {
  let html = await Bun.file(p.src).text();
  for (const [placeholder, jsFile] of Object.entries(p.inject)) {
    const js = await Bun.file(jsFile).text();
    const merged = html.replace(placeholder, "<script>\n" + js + "\n</script>");
    if (merged === html) throw new Error(`${p.src} is missing the placeholder ${placeholder}`);
    html = merged;
  }
  await Bun.write(
    p.out,
    `// GENERATED by scripts/gen-pages.ts — do not edit. Edit ${p.src} and run: bun run gen\n` +
      "export default " + JSON.stringify(html) + ";\n",
  );
  console.log("generated", p.out);
}
